TLM.f("Sancti/08-15",{"officium":"In Assumptione Beatæ Mariæ Virginis","rule":["Gloria","Credo","Prefatio=Maria=Assumptióne;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Ap 12:1"},{"k":"text","la":"Signum magnum appáruit in cœlo: múlier amicta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: quóniam mirabília fecit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Signum magnum appáruit in cœlo: múlier amicta sole, et luna sub pédibus ejus, et in cápite ejus coróna stellárum duódecim."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui Immaculátam Vírginem Maríam, Fílii tui Genetrícem, córpore et ánima ad cœléstem glóriam assumpsísti: concéde, quǽsumus; ut, ad superna semper inténti, ipsíus glóriæ mereámur esse consórtes."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Judith"},{"k":"ref","la":"Judith 13, 22-25; 15:10"},{"k":"text","la":"Benedíxit te Dóminus in virtúte sua, quia per te ad níhilum redégit inimícos nostros. Benedícta es tu, fília, a Dómino Deo excelso, præ ómnibus muliéribus super terram. Benedíctus Dóminus, qui creávit cœlum et terram, qui te diréxit in vúlnera cápitis príncipis inimicórum nostrórum; quia hódie nomen tuum ita magnificávit, ut non recédat laus tua de ore hóminum, qui mémores fúerint virtútis Dómini in ætérnum, pro quibus non pepercísti ánimæ tuæ propter angústias et tribulatiónem géneris tui, sed subvenísti ruínæ ante conspéctum Dei nostri. Tu glória Jerúsalem, tu lætítia Israël, tu honorificéntia pópuli nostri."}],"Graduale":[{"k":"ref","la":"Ps 44:11-12; 44:14"},{"k":"text","la":"Audi, fília, et vide, et inclína aurem tuam, et concupíscit rex decórem tuum."},{"k":"text","la":"Omnis glória ejus fíliæ Regis ab intus, in fímbriis áureis circumamícta varietátibus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Assumpta est María in cœlum: gaudet exércitus Angelórum. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 1:41-50"},{"k":"text","la":"In illo témpore: Repléta est Spíritu Sancto Elísabeth et exclamávit voce magna, et dixit: Benedícta tu inter mulíeres, et benedíctus fructus ventris tui. Et unde hoc mihi ut véniat mater Dómini mei ad me? Ecce enim ut facta est vox salutatiónis tuæ in áuribus meis, exsultávit in gáudio infans in útero meo. Et beáta, quæ credidísti, quóniam perficiéntur ea, quæ dicta sunt tibi a Dómino. Et ait María: Magníficat ánima mea Dóminum; et exsultávit spíritus meus in Deo salutári meo; quia respéxit humilitátem ancíllæ suæ, ecce enim ex hoc beátam me dicent omnes generatiónes. Quia fecit mihi magna qui potens est, et sanctum nomen ejus, et misericórdia ejus a progénie in progénies timéntibus eum."}],"Offertorium":[{"k":"ref","la":"Gen 3:15"},{"k":"text","la":"Inimicítias ponam inter te et mulíerem, et semen tuum et semen illíus."}],"Secreta":[{"k":"text","la":"Ascéndat ad te, Dómine, nostræ devotiónis oblátio, et, beatíssima Vírgine María in cœlum assumpta intercedénte, corda nostra, caritátis igne succénsa, ad te júgiter ádspirent."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 1:48-49"},{"k":"text","la":"Beátam me dicent omnes generatiónes, quia fecit mihi magna qui potens est."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, salutáribus sacraméntis: da, quǽsumus; ut, méritis et intercessióne beátæ Vírginis Maríæ in cœlum assúmptæ, ad resurrectiónis glóriam perducámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b533f99b700d9f54":{"t":"Otk 12, 1, Ps 97, 1\n(Otk 12, 1) Veliki se znak pokaza na nebu: žena obučena u sunce, mjesec pod njezinim nogama, a na glavi joj vijenac od dvanaest zvijezda. (Ps 97, 1) Pjevajte Gospodinu novu pjesmu, jer je učinio divote.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Otk 12, 1) Veliki se znak pokaza na nebu: žena obučena u sunce, mjesec pod njezinim nogama, a na glavi joj vijenac od dvanaest zvijezda.","v":"quia → quoniam"},"3dac73d98dc2b74e":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji si Majku tvojega jedinorođenca, neoskvrnjenu Djevicu Mariju, s tijelom i dušom uznio u nebesku slavu, podaj, molimo, da uvijek upravljeni k nebeskomu, zavrijedimo biti dionicima njezine slave.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"a939f0ec12c32247":{"t":"Jud 13, 22-25; 15, 10\nČitanje knjige Judite. Gospodin te obdario svojom snagom, i po tebi je uništio naše neprijatelje. Ti si, kćeri, blagoslovljena od Gospodina, Svevišnjega Boga, više nego sve druge žene na zemlji. Blagoslovljen Gospodin, koji je stvorio nebo i zemlju, koji je upravljao tobom, da najvećem našem neprijatelju odrubiš glavu. On je danas tako uzveličao tvoje ime, da ti pohvale neće prestati pjevati ljudi, koji će se vjekovima sjećati Božje moći. Za njih, zbog tjeskobe i nevolje svojega naroda, ti nisi štjedjela sebe nego si spriječila propast pred našim Bogom. Ti si slava Jeruzalema, ti si veselje Izraela, ti si dika roda našega!"},"478965d835afbce3":{"t":"Ps 44, 11-12 i 14\nČuj, kćeri, i vidi i prigni svoje uho, kralj će zavoljeli tvoju ljepotu. Kraljeva kći ulazi sva krasna, njezino je odijelo izvezeno zlatom.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nUznesena je Marija na nebo, raduje se vojska anđela. <i>Aleluja</i>.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.89)"},"dec5728a39f2a4d1":{"t":"Lk 1, 41-50\nSlijedi sveto Evanđelje po Luki. U ono vrijeme, Elizabeta nadahnuta Duhom Svetim klikne jakim glasom; Blagoslovljena ti medu ženama i blagoslovljen plod utrobe tvoje! Tko sam ja, da majka mojega Gospodina dolazi k meni? I eto, čim sam čula tvoj pozdrav, od radosti dijete zaigra u meni. Blago tebl. koja si vjerovala, da će se ispuniti što ti je rekao Gospodin. Marija tada reče: Veliča duša moja Gospodina, i moj se duh raduje u Bogu, mojem Spasitelju. On je pogledao na poniznost svoje službenice, i gle! Odsad će me zvati blaženom sva pokoljenja. Velika dobročinstva iskazao mi je Svemogući, i sveto je ime njegovo. I njegovo je milosrđe uvijek nad onima, koji ga se boje!"},"371820b745506740":{"t":"Post 3, 15\nPostavit ću neprijateljstvo između tebe i žene, između tvojega i njezina potomstva."},"ffb0e943b12ac32b":{"t":"Uzašao k tebi, Gospodine, prinos naše odanosti, i na zagovor blažene Djevice Marije na nebo uznesene naša srca rasplamćena ognjem ljubavi neka uvijek k tebi teže.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"ab61d05c031233d0":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o uznesenju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"94a5ee289ff4b212":{"t":"Lk 1, 48-49\nSvi će me naraštaji zvati blaženom, jer mi je velika dobročistva iskazao onaj koji je silan."},"b5c3d99ee7885591":{"t":"<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.\nPodaj, molimo, Gospodine, da mi, koji smo primili otajstva spasenja, pa zagovoru i zaslugama blažene Djevice Marije na nebo uznesene budemo privedeni k slavi uskrsnuća.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
